import subprocess, time, json, urllib.request, urllib.error, urllib.parse

def req(path):
    url = f'http://127.0.0.1:8028{path}'
    try:
        with urllib.request.urlopen(url, timeout=3) as resp:
            return resp.status, resp.read().decode('utf-8', errors='replace')
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode('utf-8', errors='replace')

def output_of(body):
    try:
        return json.loads(body).get('output', '')
    except json.JSONDecodeError:
        return body

srv = subprocess.Popen(['node', 'server.js'])
try:
    ok = False
    for _ in range(30):
        try:
            status, body = req('/greet-cmd?name=Alice')
            ok = True
            break
        except (urllib.error.URLError, ConnectionResetError):
            time.sleep(0.5)
    assert ok, 'server never became reachable on :8028'
    assert status == 200, f'expected 200 for legitimate input, got {status} {body!r}'
    data = json.loads(body)
    assert 'Hello, Alice' in data.get('output', ''), f'legitimate input broken: {data!r}'

    # For each payload, a SAFE fix either (a) never lets the shell interpret the
    # metacharacters - in which case the literal payload text (semicolons, $(),
    # backticks and all) comes back untouched inside the output, proving nothing
    # was executed - or (b) rejects the input outright with 400. A VULNERABLE
    # implementation lets the shell interpret/strip the metacharacters, so the
    # literal payload text is NOT found intact in the response.
    payloads = [
        'world; echo INJECTED_MARKER',
        '$(echo INJECTED2)',
        '`echo INJECTED3`',
    ]
    for payload in payloads:
        status, body = req('/greet-cmd?name=' + urllib.parse.quote(payload))
        if status == 400:
            continue  # sanitize-and-reject strategy: also a valid fix
        assert status == 200, f'unexpected status {status} for payload {payload!r}: {body!r}'
        out = output_of(body)
        assert payload in out, (
            f'shell metacharacters in {payload!r} were interpreted/stripped instead of '
            f'being treated as literal, inert text - command injection succeeded: {out!r}'
        )
finally:
    srv.terminate()
    try:
        srv.wait(timeout=5)
    except Exception:
        srv.kill()
print('PASS')
